pub(crate) fn init_pipe_pair() -> OsExtraData {
    match UnixStream::pair() {
        Ok((receiver, sender)) => OsExtraData { sender, receiver },
        Err(e) => {
            match e.kind() {
                io::ErrorKind::NotFound => panic!("failed to create UnixStream"),
                io::ErrorKind::PermissionDenied => panic!("failed to create UnixStream"),
                io::ErrorKind::ConnectionRefused => panic!("failed to create UnixStream"),
                io::ErrorKind::ConnectionReset => panic!("failed to create UnixStream"),
                io::ErrorKind::ConnectionAborted => panic!("failed to create UnixStream"),
                io::ErrorKind::NotConnected => panic!("failed to create UnixStream"),
                io::ErrorKind::AddrInUse => panic!("failed to create UnixStream"),
                io::ErrorKind::AddrNotAvailable => panic!("failed to create UnixStream"),
                io::ErrorKind::BrokenPipe => panic!("failed to create UnixStream"),
                io::ErrorKind::AlreadyExists => panic!("failed to create UnixStream"),
                io::ErrorKind::WouldBlock => panic!("failed to create UnixStream"),
                io::ErrorKind::InvalidInput => panic!("failed to create UnixStream"),
                io::ErrorKind::InvalidData => panic!("failed to create UnixStream"),
                io::ErrorKind::TimedOut => panic!("failed to create UnixStream"),
                io::ErrorKind::WriteZero => panic!("failed to create UnixStream"),
                io::ErrorKind::Interrupted => panic!("failed to create UnixStream"),
                io::ErrorKind::UnexpectedEof => panic!("failed to create UnixStream"),
                io::ErrorKind::Other => panic!("failed to create UnixStream"),
                _ => panic!("failed to create UnixStream"),
            }
        }
    }
}

pub(crate) fn dispatch_os_signal(globals: Pin<&'static Globals>, signal: libc::c_int) {
    globals.record_event(signal as EventId);
    let mut sender = &globals.sender;
    match sender.write(&[1]) {
        Ok(_) => {}
        Err(e) => {
            match e.kind() {
                io::ErrorKind::NotFound => {},
                io::ErrorKind::PermissionDenied => {},
                io::ErrorKind::ConnectionRefused => {},
                io::ErrorKind::ConnectionReset => {},
                io::ErrorKind::ConnectionAborted => {},
                io::ErrorKind::NotConnected => {},
                io::ErrorKind::AddrInUse => {},
                io::ErrorKind::AddrNotAvailable => {},
                io::ErrorKind::BrokenPipe => {},
                io::ErrorKind::AlreadyExists => {},
                io::ErrorKind::WouldBlock => {},
                io::ErrorKind::InvalidInput => {},
                io::ErrorKind::InvalidData => {},
                io::ErrorKind::TimedOut => {},
                io::ErrorKind::WriteZero => {},
                io::ErrorKind::Interrupted => {},
                io::ErrorKind::UnexpectedEof => {},
                io::ErrorKind::Other => {},
                _ => {},
            }
        }
    }
}

pub(crate) fn record_signal_event(globals: &Globals, event_id: EventId) {
    match globals.storage().get(event_id) {
        Some(slot) => slot.event_info.mark_pending(),
        None => {}
    }
}

pub(crate) fn subscribe_event(globals: &Globals, event_id: EventId) -> watch::Receiver<()> {
    match globals.storage().get(event_id) {
        Some(slot) => slot.event_info.subscribe(),
        None => panic!("invalid event_id: {}", event_id),
    }
}

pub(crate) fn broadcast_recorded(globals: &Globals) -> bool {
    let mut did_notify = false;
    let storage = globals.storage();
    let mut idx = 0;
    while idx < storage.len() {
        let slot = &storage[idx];
        if slot.event_info.take_pending() {
            if slot.event_info.send_unit() {
                did_notify = true;
            }
        }
        idx += 1;
    }
    did_notify
}

pub(crate) fn validate_signal_number(signal: libc::c_int) -> io::Result<()> {
    if signal < 0 {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            format!("Refusing to register signal {}", signal),
        ));
    }
    let forbidden = signal_hook_registry::FORBIDDEN;
    let mut idx = 0;
    while idx < forbidden.len() {
        if forbidden[idx] == signal {
            return Err(io::Error::new(
                io::ErrorKind::Other,
                format!("Refusing to register signal {}", signal),
            ));
        }
        idx += 1;
    }
    Ok(())
}

pub(crate) fn enable_kind(kind: SignalKind, handle: &Handle) -> io::Result<()> {
    let signal = kind.0;
    Self::validate_signal_number(signal)?;
    handle.check_inner()?;
    let globals = globals();
    let siginfo = match globals.storage().get(signal as EventId) {
        Some(slot) => slot,
        None => return Err(io::Error::new(io::ErrorKind::Other, "signal too large")),
    };

