    pub(crate) fn open_listener(
        kind: SignalKind,
        handle: &Handle,
    ) -> io::Result<watch::Receiver<()>> {
        Self::enable_kind(kind, handle)?;
        Ok(globals().register_listener(kind.0 as EventId))
    }

    #[track_caller]
    pub(crate) fn install_signal(kind: SignalKind) -> io::Result<Signal> {
        let rx = Self::open_listener(kind, &Handle::current())?;
        Ok(Signal {
            inner: RxFuture::new(rx),
        })
    }

    /// Returns a handle to this event loop which can be sent across threads
    /// and can be used as a proxy to the event loop itself.
    pub(crate) fn handle(&self) -> Handle {
        Handle {
            inner: Arc::downgrade(&self.inner),
        }
    }

    fn park_io_driver(&mut self) -> io::Result<()> {
        match self.park.park() {
            Ok(()) => Ok(()),
            Err(e) => {
                match e.kind() {
                    io::ErrorKind::NotFound => return Err(e),
                    io::ErrorKind::PermissionDenied => return Err(e),
                    io::ErrorKind::ConnectionRefused => return Err(e),
                    io::ErrorKind::ConnectionReset => return Err(e),
                    io::ErrorKind::ConnectionAborted => return Err(e),
                    io::ErrorKind::NotConnected => return Err(e),
                    io::ErrorKind::AddrInUse => return Err(e),
                    io::ErrorKind::AddrNotAvailable => return Err(e),
                    io::ErrorKind::BrokenPipe => return Err(e),
                    io::ErrorKind::AlreadyExists => return Err(e),
                    io::ErrorKind::WouldBlock => return Err(e),
                    io::ErrorKind::InvalidInput => return Err(e),
                    io::ErrorKind::InvalidData => return Err(e),
                    io::ErrorKind::TimedOut => return Err(e),
                    io::ErrorKind::WriteZero => return Err(e),
                    io::ErrorKind::Interrupted => return Err(e),
                    io::ErrorKind::UnexpectedEof => return Err(e),
                    io::ErrorKind::Other => return Err(e),
                    _ => return Err(e),
                }
            }
        }
    }

